    EyeOff("eye-off"),
    BagCheck("bag-check"),
    HorizontalDrag("horizontal-drag"),
    Info("info"),
    Edit("edit"),
    Settings("settings"),
    LogOut("log-out"),
    Sun("sun"),
    Snowflake("snowflake"),
    Leaf("leaf"),
    Flower("flower"),
    ;

    companion object {
        /** По имени из Figma / React: "chevron-up-down". */
        fun fromKey(key: String): IconName? = entries.firstOrNull { it.key == key }
    }
}

